def split_section_from_s3_key(apps, schema_editor):
    """
    1차 데이터 이전(09 문서 2-9): s3_key에 들어 있던 구간 이름(first_description 등)을 section으로 옮기고,
    s3_key에는 url(/media/...)에서 뽑은 스토리지 상대키(CDN 업로드 경로)를 넣는다.
    """
    ExerciseMedia = apps.get_model('exercises', 'ExerciseMedia')
    for media in ExerciseMedia.objects.all():
        changed = False
        if media.s3_key and '/' not in media.s3_key:
            media.section = media.s3_key
            media.s3_key = None
            changed = True
        if not media.s3_key and media.url and not media.url.startswith(('http://', 'https://')):
            key = media.url[len('/media/'):] if media.url.startswith('/media/') else media.url
            media.s3_key = key.lstrip('/')
            changed = True
        if changed:
            media.save(update_fields=['section', 's3_key'])


def merge_section_back(apps, schema_editor):
    ExerciseMedia = apps.get_model('exercises', 'ExerciseMedia')
    for media in ExerciseMedia.objects.exclude(section__isnull=True):
        media.s3_key = media.section
        media.save(update_fields=['s3_key'])


